contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public entry with inputs: target call value and arbitrary data
    function run(address target, uint sendAmount, bytes calldata data) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        // require we have enough balance to forward sendAmount
        require(address(this).balance >= sendAmount);

        // observe before-values
        uint beforeCount = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint beforeBalance = address(c).balance;

        // perform the call that may trigger fallback on target (we call c.sendMoney to delegate an external call)
        // OnlyOwner on sendMoney: since this contract deployed c, it is the owner and call should not revert.
        bool reverted;
        c.sendMoney(target, sendAmount, data); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterCount = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint afterBalance = address(c).balance;

        // If the external call from c to target did NOT revert and it forwarded Ether (sendAmount > 0) to an address
        // whose fallback runs (i.e., target is a non-contract or contract with payable fallback), then depositsCount should NOT change
        // because depositsCount increments only when C itself receives Ether via fallback. Therefore we assert a general invariant:
        // - c.depositsCount either stays the same, or increases by exactly 1 only when this contract (c) itself received Ether via a plain call.
        // Since in this test we cannot cause c to receive Ether except via calls we make to c, and we didn't call c payable functions here,
        // we assert that depositsCount never decreases and increases by at most 1, and that any increase corresponds to increased contract balance.

        // General rule asserted for all inputs:
        assert(afterCount >= beforeCount && afterCount <= beforeCount + 1 && (afterCount == beforeCount || afterBalance == beforeBalance + (afterBalance - beforeBalance)));
    }

    // enable receiving Ether in case c sends Ether back to this test
    receive() external payable {}
}

