// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(address target, uint256 sendAmount, bytes memory data) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= sendAmount);
        uint256 beforeCount;
        try c.depositsCount() returns (uint256 __r) { beforeCount = __r; } catch { return; }
        uint beforeBalance = address(c).balance;
        bool reverted;
        try c.sendMoney(target, sendAmount, data) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterCount;
        try c.depositsCount() returns (uint256 __r) { afterCount = __r; } catch { return; }
        uint afterBalance = address(c).balance;
        assertTrue(afterCount >= beforeCount && afterCount <= beforeCount + 1 && (afterCount == beforeCount || afterBalance == beforeBalance + (afterBalance - beforeBalance)));
    }

    function testFuzz_run(address target, uint256 sendAmount, bytes memory data) public {
        vm.assume(target.code.length == 0 && uint160(target) > 0xffff && target != address(this) && target != address(c) && target != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && target != 0x000000000000000000636F6e736F6c652e6c6f67 && target != 0x4e59b44847b379578588920cA78FbF26c0B4956C && target != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(target, sendAmount, data);
    }

    receive() external payable {}
}
